def min_max_reduction_game(nums):
    values=list(nums)
    while len(values)>1:
        values=[min(values[2*index],values[2*index+1]) if index%2==0 else max(values[2*index],values[2*index+1]) for index in range(len(values)//2)]
    return values[0]

